mapper.select:
SELECT FROM agri_md_organization o LEFT JOIN agri_md_organization p ON p.id = o.parent_id AND p.del_flag = 0 WHERE o.del_flag = 0 AND o.parent_id = #{parentId}
AND o.tenant_id = CONVERT(#{tenantId} USING utf8mb4) COLLATE utf8mb4_unicode_ci
ORDER BY o.org_name ASC, o.id ASC

mapper.sql:
o.del_flag = 0

    AND o.tenant_id = CONVERT(#{tenantId} USING utf8mb4) COLLATE utf8mb4_unicode_ci


    AND o.org_name LIKE CONCAT('%', #{orgName}, '%')


    AND (
        o.org_name LIKE CONCAT('%', #{keyword}, '%')
        OR o.org_code LIKE CONCAT('%', #{keyword}, '%')
        OR o.contact_person LIKE CONCAT('%', #{keyword}, '%')
    )


    AND o.org_type = #{orgType}


    AND o.status = #{status}
